function sameOrigin (req) {
  if (!req.headers.origin) return false
  try {
    const origin = new URL(req.headers.origin)
    return origin.host === req.headers.host &&
      origin.protocol === (req.socket.encrypted ? 'https:' : 'http:')
  } catch (_) { return false }
}

function replyJson (res, status, data, headers = {}) {
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    ...headers
  })
  res.end(JSON.stringify(data))
}

async function readJsonBody (req, maxBytes) {
  if (String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase() !== 'application/json') {
    throw new Error('JSON body required')
  }
  let raw
  if (req.body !== undefined) {
    // MUSE's middleware can expose an empty placeholder object while the raw
    // JSON bytes are still on the request stream. Keep the legacy fallback so
    // login and Apply receive the actual payload on that runtime.
    const hasParsedObject = req.body && typeof req.body === 'object' &&
      !Buffer.isBuffer(req.body) && !Array.isArray(req.body) &&
      Object.keys(req.body).length > 0
    if (Buffer.isBuffer(req.body) || typeof req.body === 'string' || hasParsedObject) {
      raw = Buffer.isBuffer(req.body) ? req.body
        : typeof req.body === 'string' ? Buffer.from(req.body) : Buffer.from(JSON.stringify(req.body))
    }
  }
  if (raw === undefined && typeof req[Symbol.asyncIterator] === 'function') {
    const chunks = []
    let size = 0
    for await (const chunk of req) {
      const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)
      size += bytes.length
      if (size > maxBytes) throw new Error('Request too large')
      chunks.push(bytes)
    }
    raw = Buffer.concat(chunks)
  }
  if (raw === undefined) {
    const value = req.body === undefined ? {} : req.body
    raw = Buffer.from(JSON.stringify(value))
  }
  if (raw.length > maxBytes) throw new Error('Request too large')
  const value = JSON.parse(raw.toString('utf8'))
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('JSON object required')
  return value
}

// Serialized into the Vue component, so keep this function browser-only and self-contained.
async function fetchWithTimeout (url, options = {}, timeoutMs = 12000, readResponse) {
  const controller = new AbortController()
  let timedOut = false
  const timer = setTimeout(() => { timedOut = true; controller.abort() }, timeoutMs)
  try {
    const response = await fetch(url, { ...options, signal: controller.signal })
    return readResponse ? await readResponse(response) : response
  } catch (error) {
    if (timedOut) throw new Error('Request timed out; your binding draft is still available')
    throw error
  } finally {
    clearTimeout(timer)
  }
}

// Keep the deadline active through JSON decoding, not just response headers.
async function runtimeJsonRequest (url, options, { fetcher = fetch, timeoutMs, operation }) {
  const controller = new AbortController()
  let timedOut = false
  const timer = setTimeout(() => { timedOut = true; controller.abort() }, timeoutMs)
  try {
    const response = await fetcher(url, { ...options, signal: controller.signal })
    if (!response.ok) return { response, data: null }
    return { response, data: await response.json() }
  } catch (cause) {
    const error = new Error(`${operation} ${timedOut ? 'timed out' : 'failed'}; ${timedOut ? 'the runtime did not respond in time' : cause.message}`, { cause })
    error.status = 503
    throw error
  } finally {
    clearTimeout(timer)
  }
}

module.exports = { sameOrigin, replyJson, readJsonBody, fetchWithTimeout, runtimeJsonRequest }
